1	import Foundation
2	import BackgroundTasks
3	import SwiftData
4	import WCIWKit
5	
6	@MainActor
7	final class BackgroundTaskManager {
8	    static let shared = BackgroundTaskManager()
9	
10	    static let availabilityCheckIdentifier = "com.tommcfarlin.watchit.availability-check"
11	
12	    private init() {}
13	
14	    // MARK: - Registration
15	
16	    func registerTasks() {
17	        BGTaskScheduler.shared.register(
18	            forTaskWithIdentifier: Self.availabilityCheckIdentifier,
19	            using: nil
20	        ) { task in
21	            guard let refreshTask = task as? BGAppRefreshTask else { return }
22	            Task { @MainActor in
23	                await self.handleAvailabilityCheck(task: refreshTask)
24	            }
25	        }
26	    }
27	
28	    func scheduleAvailabilityCheck() {
29	        let request = BGAppRefreshTaskRequest(identifier: Self.availabilityCheckIdentifier)
30	        // Request no earlier than 2 hours from now
31	        request.earliestBeginDate = Date(timeIntervalSinceNow: 2 * 60 * 60)
32	
33	        do {
34	            try BGTaskScheduler.shared.submit(request)
35	        } catch {
36	            // Non-fatal — iOS may reject scheduling
37	        }
38	    }
39	
40	    // MARK: - Task Handling
41	
42	    private func handleAvailabilityCheck(task: BGAppRefreshTask) async {
43	        // Schedule the next check before starting work
44	        scheduleAvailabilityCheck()
45	
46	        // Only check if premium and notifications enabled
47	        guard NotificationManager.shared.shouldScheduleNotifications() else {
48	            task.setTaskCompleted(success: true)
49	            return
50	        }
51	
52	        guard let tmdbService = try? TMDBService() else {
53	            task.setTaskCompleted(success: false)
54	            return
55	        }
56	
57	        let userServiceIDs = UserServicesManager.shared.selectedServiceIDs
58	        guard !userServiceIDs.isEmpty else {
59	            task.setTaskCompleted(success: true)
60	            return
61	        }
62	
63	        // Set up expiration handler
64	        task.expirationHandler = {
65	            // Task ran out of time — will try again next cycle
66	        }
67	
68	        do {
69	            // Create a model container to access watchlist data
70	            let schema = Schema([WatchlistItem.self])
71	            let config = ModelConfiguration(schema: schema, isStoredInMemoryOnly: false, cloudKitDatabase: .none)
72	            let container = try ModelContainer(for: schema, configurations: [config])
73	            let context = ModelContext(container)
74	
75	            // Fetch movies that haven't been notified yet
76	            let descriptor = FetchDescriptor<WatchlistItem>(
77	                predicate: #Predicate<WatchlistItem> {
78	                    $0.hasNotifiedAvailability == false
79	                }
80	            )
81	            let items = (try? context.fetch(descriptor)) ?? []
82	            let movies = items.filter { $0.isMovie }
83	
84	            // Check each movie's availability
85	            for movie in movies {
86	                let media = movie.toMedia()
87	
88	                do {
89	                    let availability = try await tmdbService.getWatchProviders(for: media)
90	                    let streamingProviders = availability.flatrate
91	
92	                    if let serviceName = NotificationContentBuilder.matchingServiceName(
93	                        providers: streamingProviders,
94	                        userServiceIDs: userServiceIDs
95	                    ) {
96	                        // Match found — notify and mark
97	                        await NotificationManager.shared.notifyMovieAvailable(
98	                            item: movie,
99	                            serviceName: serviceName
100	                        )
101	                        movie.hasNotifiedAvailability = true
102	                    }
103	                } catch {
104	                    // Skip this movie, try next
105	                    continue
106	                }
107	            }
108	
109	            // Also reschedule episode notifications
110	            let allItems = (try? context.fetch(FetchDescriptor<WatchlistItem>())) ?? []
111	            await NotificationManager.shared.rescheduleEpisodeNotifications(items: allItems)
112	
113	            try? context.save()
114	            task.setTaskCompleted(success: true)
115	        } catch {
116	            task.setTaskCompleted(success: false)
117	        }
118	    }
119	}
